import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-12/rl_series_01_problem_boundary.png",l="/Nav2ArticlesSite/article-assets/2026-08-12/rl_series_01_agent_environment_loop.png",n="/Nav2ArticlesSite/article-assets/2026-08-12/rl_series_01_long_term_consequence.png",h="/Nav2ArticlesSite/article-assets/2026-08-12/rl_series_01_autonomous_driving_map.png",s="/Nav2ArticlesSite/article-assets/2026-08-12/rl_series_01_rl_decision_framework.png",P=JSON.parse('{"title":"强化学习到底在解决什么问题？先别急着训练智能体","description":"打开一本强化学习教程，最容易做的事是立刻寻找算法：Q-learning（Q 学习）怎么更新，DQN（深度 Q 网络）怎么写，PPO（近端策略优化）为什么稳定。但真正决定项目成败的，往往不是算法名字，而是更早的问题：你面对的任务，究竟是不是一个值得用强化学习解决的连续决策问题？","frontmatter":{"title":"强化学习到底在解决什么问题？先别急着训练智能体","description":"打开一本强化学习教程，最容易做的事是立刻寻找算法：Q-learning（Q 学习）怎么更新，DQN（深度 Q 网络）怎么写，PPO（近端策略优化）为什么稳定。但真正决定项目成败的，往往不是算法名字，而是更早的问题：你面对的任务，究竟是不是一个值得用强化学习解决的连续决策问题？","date":"2026-08-12","topic":"强化学习","section":"强化学习分类系列","readingTime":15,"source":"2026-08-12/rl_series_01_what_problem_does_rl_solve.md","status":"published","cover":"/article-assets/2026-08-12/rl_series_01_problem_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-01-what-problem-does-rl-solve"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"强化学习到底在解决什么问题？先别急着训练智能体"}],["meta",{"property":"og:description","content":"打开一本强化学习教程，最容易做的事是立刻寻找算法：Q-learning（Q 学习）怎么更新，DQN（深度 Q 网络）怎么写，PPO（近端策略优化）为什么稳定。但真正决定项目成败的，往往不是算法名字，而是更早的问题：你面对的任务，究竟是不是一个值得用强化学习解决的连续决策问题？"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-01-what-problem-does-rl-solve"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-12/rl_series_01_problem_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-08-12"}],["meta",{"name":"twitter:title","content":"强化学习到底在解决什么问题？先别急着训练智能体"}],["meta",{"name":"twitter:description","content":"打开一本强化学习教程，最容易做的事是立刻寻找算法：Q-learning（Q 学习）怎么更新，DQN（深度 Q 网络）怎么写，PPO（近端策略优化）为什么稳定。但真正决定项目成败的，往往不是算法名字，而是更早的问题：你面对的任务，究竟是不是一个值得用强化学习解决的连续决策问题？"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-12/rl_series_01_problem_boundary.png"}]],"prev":false,"next":{"text":"别再把状态和观测混为一谈：拆开强化学习的六个核心概念","link":"/rl/rl-series-02-agent-environment-state-action-reward"}},"headers":[],"relativePath":"rl/rl-series-01-what-problem-does-rl-solve.md","filePath":"rl/rl-series-01-what-problem-does-rl-solve.md","lastUpdated":null}'),p={name:"rl/rl-series-01-what-problem-does-rl-solve.md"};function d(c,a,_,u,m,b){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="强化学习到底在解决什么问题-先别急着训练智能体" tabindex="-1">强化学习到底在解决什么问题？先别急着训练智能体 <a class="header-anchor" href="#强化学习到底在解决什么问题-先别急着训练智能体" aria-label="Permalink to &quot;强化学习到底在解决什么问题？先别急着训练智能体&quot;">​</a></h1><p>打开一本强化学习教程，最容易做的事是立刻寻找算法：Q-learning（Q 学习）怎么更新，DQN（深度 Q 网络）怎么写，PPO（近端策略优化）为什么稳定。但真正决定项目成败的，往往不是算法名字，而是更早的问题：你面对的任务，究竟是不是一个值得用强化学习解决的连续决策问题？</p><p><img src="'+o+'" alt="强化学习问题边界"></p><h2 id="一、结论先说" tabindex="-1">一、结论先说 <a class="header-anchor" href="#一、结论先说" aria-label="Permalink to &quot;一、结论先说&quot;">​</a></h2><p>强化学习（Reinforcement Learning，强化学习）适合处理这样的任务：智能体需要连续地与环境交互，当前动作会改变未来状态，正确动作难以被逐步标注，反馈可能延迟，而且学习者必须在探索未知方案与利用已有经验之间权衡。</p><p>这一定义里，关键不是“用了神经网络”，也不是“能自动调参数”，而是连续决策、长期后果和交互数据。少掉这些条件，问题很可能更适合监督学习（Supervised Learning，监督学习）、搜索、优化或经典控制。</p><p>对自动驾驶尤其如此。感知、预测、决策和控制都可以使用机器学习，但它们并不因此都属于强化学习。车道线识别通常有标签可学；轨迹预测可以从历史数据中监督训练；车辆横向控制可能已有稳定的 Stanley（斯坦利）控制器；只有当动作持续改变后续局面、需要权衡长期收益且无法直接给出每一步标准答案时，强化学习才真正进入自己的主场。</p><p>所以，学习强化学习的起点不该是“选哪个算法”，而应该是“识别哪类问题”。</p><h2 id="二、强化学习处理的是连续决策" tabindex="-1">二、强化学习处理的是连续决策 <a class="header-anchor" href="#二、强化学习处理的是连续决策" aria-label="Permalink to &quot;二、强化学习处理的是连续决策&quot;">​</a></h2><h3 id="_2-1-一个动作会改变后面的世界" tabindex="-1">2.1 一个动作会改变后面的世界 <a class="header-anchor" href="#_2-1-一个动作会改变后面的世界" aria-label="Permalink to &quot;2.1 一个动作会改变后面的世界&quot;">​</a></h3><p>在普通分类任务中，一张图片被识别成汽车还是卡车，通常不会改变下一张图片的内容。训练样本可以提前收集，模型对某个样本的输出也不会回头改写数据集。</p><p>强化学习不同。智能体在状态中选择动作，环境根据动作转移到新状态，再给出奖励或代价。新状态不是背景材料，而是刚才那个动作造成的后果。智能体随后看到什么、还能选择什么、是否接近失败，都被之前的动作影响。</p><p><img src="'+l+'" alt="智能体与环境的闭环"></p><p>以自动驾驶汇入主路为例。车辆选择加速，不只是让当前速度变大，也会改变与前后车的相对距离、可接受间隙、未来碰撞风险和后续可选轨迹。一个动作看似只持续零点几秒，却可能改变几秒后的整个决策空间。</p><p>这就是序列决策（Sequential Decision Making，序列决策）的核心：评价动作时，不能只问“此刻是否正确”，还要问“它把系统带到了怎样的未来”。</p><h3 id="_2-2-数据分布由策略自己制造" tabindex="-1">2.2 数据分布由策略自己制造 <a class="header-anchor" href="#_2-2-数据分布由策略自己制造" aria-label="Permalink to &quot;2.2 数据分布由策略自己制造&quot;">​</a></h3><p>强化学习中的策略（Policy，策略）决定智能体在不同状态下如何选择动作。策略一变，智能体访问到的状态也会变，采集到的数据分布随之变化。</p><p>一个保守的合流策略可能长期停在匝道上，因此很少观察到高速车流中的交互状态；一个激进策略会频繁进入小间隙，也就更容易收集到临界冲突数据。训练数据并不是一份静止的题库，而是当前策略与环境共同生成的轨迹（Trajectory，轨迹）。</p><p>这种闭环让强化学习比“拿固定数据集训练一次”更难。策略的早期偏差可能让智能体反复进入狭窄的状态区域，进一步限制它能学到的经验。数据质量影响策略，策略又反过来决定数据质量。</p><h3 id="_2-3-探索本身带有代价" tabindex="-1">2.3 探索本身带有代价 <a class="header-anchor" href="#_2-3-探索本身带有代价" aria-label="Permalink to &quot;2.3 探索本身带有代价&quot;">​</a></h3><p>智能体如果只重复已知动作，可能永远发现不了更优策略；如果频繁尝试未知动作，又可能损失奖励甚至触发危险。探索（Exploration，探索）与利用（Exploitation，利用）的矛盾因此贯穿整个学习过程。</p><p>在游戏中，失败通常意味着重新开局；在真实车辆上，越线、碰撞或失稳不能被当成普通训练样本。可探索并不等于可在真实系统里随意试错。自动驾驶强化学习通常需要仿真、离线数据、约束、备份控制器和独立安全评估共同工作。</p><h2 id="三、奖励不是监督学习里的标签" tabindex="-1">三、奖励不是监督学习里的标签 <a class="header-anchor" href="#三、奖励不是监督学习里的标签" aria-label="Permalink to &quot;三、奖励不是监督学习里的标签&quot;">​</a></h2><h3 id="_3-1-标签回答局部输出是否正确" tabindex="-1">3.1 标签回答局部输出是否正确 <a class="header-anchor" href="#_3-1-标签回答局部输出是否正确" aria-label="Permalink to &quot;3.1 标签回答局部输出是否正确&quot;">​</a></h3><p>监督学习通常拥有输入与目标输出的对应关系。给定一张图片，标签可以直接告诉模型类别；给定一段历史轨迹，数据集可以提供未来轨迹作为训练目标。损失函数衡量预测与目标之间的差距，反馈直接作用在当前样本上。</p><p>如果一个驾驶任务能够稳定地为每个状态提供专家动作，那么模仿学习（Imitation Learning，模仿学习）或行为克隆（Behavior Cloning，行为克隆）往往是更直接的起点。它们也有分布偏移等问题，但不必从稀疏的长期回报中反推每一步动作的贡献。</p><h3 id="_3-2-奖励评价一段行为的长期后果" tabindex="-1">3.2 奖励评价一段行为的长期后果 <a class="header-anchor" href="#_3-2-奖励评价一段行为的长期后果" aria-label="Permalink to &quot;3.2 奖励评价一段行为的长期后果&quot;">​</a></h3><p>强化学习中的奖励（Reward，奖励）通常只表达环境对结果的反馈，并不直接告诉智能体“正确动作应该是什么”。一次礼让可能暂时降低速度，却让后续合流更平顺；一次抢行可能立刻获得进度，却在几秒后迫使车辆急刹。</p><p>于是出现信用分配（Credit Assignment，信用分配）问题：最终成功或失败，究竟该归因于轨迹中的哪些动作？奖励越延迟、轨迹越长、环境随机性越强，归因就越困难。</p><p><img src="'+n+'" alt="即时收益与长期后果"></p><p>回报（Return，回报）把未来一段时间的奖励聚合起来，折扣因子（Discount Factor，折扣因子）控制智能体看重近期还是远期结果。它让“长期更好”能够被数学表达，却不会自动保证奖励设计正确。</p><h3 id="_3-3-奖励函数不能替代任务定义" tabindex="-1">3.3 奖励函数不能替代任务定义 <a class="header-anchor" href="#_3-3-奖励函数不能替代任务定义" aria-label="Permalink to &quot;3.3 奖励函数不能替代任务定义&quot;">​</a></h3><p>奖励函数不是一句“越大越好”就结束了。效率、舒适、规则遵从、能耗与安全可能相互冲突。把所有目标压成一个加权和，会让权重选择直接决定策略偏好，也可能产生奖励投机（Reward Hacking，奖励投机）：智能体找到了高分方式，却没有完成设计者真正关心的任务。</p><p>例如，只奖励纵向进度，策略可能频繁急加速；只惩罚碰撞，策略可能停着不动；把越线设置成有限惩罚，策略可能在足够大的效率奖励面前接受越线。数值分数并不会理解工程意图。</p><p>安全问题尤其不应只藏在奖励里。约束强化学习（Constrained Reinforcement Learning，约束强化学习）会把某些风险作为独立代价或约束报告，而不是默认“高回报等于安全”。在本项目的小规模实验中，<code>episode_return</code>（回合回报）也不能单独证明策略安全；还需要观察约束违反率、最大违反量、首次违反时刻和安全层介入率。</p><h2 id="四、什么问题值得使用强化学习" tabindex="-1">四、什么问题值得使用强化学习 <a class="header-anchor" href="#四、什么问题值得使用强化学习" aria-label="Permalink to &quot;四、什么问题值得使用强化学习&quot;">​</a></h2><h3 id="_4-1-存在连续交互闭环" tabindex="-1">4.1 存在连续交互闭环 <a class="header-anchor" href="#_4-1-存在连续交互闭环" aria-label="Permalink to &quot;4.1 存在连续交互闭环&quot;">​</a></h3><p>任务需要反复经历“观察—动作—环境变化—新观察”。如果模型只做一次预测，输出不会改变后续输入，强化学习通常不是首选。</p><h3 id="_4-2-当前动作影响未来机会" tabindex="-1">4.2 当前动作影响未来机会 <a class="header-anchor" href="#_4-2-当前动作影响未来机会" aria-label="Permalink to &quot;4.2 当前动作影响未来机会&quot;">​</a></h3><p>动作不仅产生即时结果，还会改变未来状态、信息或可选动作。合流、交叉口博弈、跟车策略和多车协作都有这种性质。相反，独立图片分类几乎没有长期动作后果。</p><h3 id="_4-3-很难逐步给出最优动作" tabindex="-1">4.3 很难逐步给出最优动作 <a class="header-anchor" href="#_4-3-很难逐步给出最优动作" aria-label="Permalink to &quot;4.3 很难逐步给出最优动作&quot;">​</a></h3><p>设计者能评价整段行为是否高效、舒适或成功，却很难为每个时刻标注唯一正确动作。多个动作都可能合理，它们的好坏要到后续才能显现。</p><h3 id="_4-4-环境能提供可重复反馈" tabindex="-1">4.4 环境能提供可重复反馈 <a class="header-anchor" href="#_4-4-环境能提供可重复反馈" aria-label="Permalink to &quot;4.4 环境能提供可重复反馈&quot;">​</a></h3><p>学习需要大量交互或可靠的离线轨迹。仿真器必须具有足够可信的动力学、交通参与者行为和随机性；离线数据必须覆盖与目标策略相关的状态。如果环境反馈失真，算法只会更有效地优化错误世界。</p><h3 id="_4-5-强基线仍存在明确缺口" tabindex="-1">4.5 强基线仍存在明确缺口 <a class="header-anchor" href="#_4-5-强基线仍存在明确缺口" aria-label="Permalink to &quot;4.5 强基线仍存在明确缺口&quot;">​</a></h3><p>使用强化学习之前，应先建立 baseline（基线）。如果简单规则、搜索、模型预测控制或经典控制已经稳定解决任务，而且成本更低、解释性更强，就没有必要为了“智能化”而替换它。</p><p>强化学习的合理入口不是“基线看起来传统”，而是基线在长期权衡、复杂交互、未知模型或组合决策上存在可重复的缺口。</p><h2 id="五、什么问题不该优先使用强化学习" tabindex="-1">五、什么问题不该优先使用强化学习 <a class="header-anchor" href="#五、什么问题不该优先使用强化学习" aria-label="Permalink to &quot;五、什么问题不该优先使用强化学习&quot;">​</a></h2><h3 id="_5-1-有清晰标签的感知任务" tabindex="-1">5.1 有清晰标签的感知任务 <a class="header-anchor" href="#_5-1-有清晰标签的感知任务" aria-label="Permalink to &quot;5.1 有清晰标签的感知任务&quot;">​</a></h3><p>目标检测、语义分割、车道线识别等任务通常有明确标注和成熟监督学习范式。即使它们服务于驾驶闭环，也不意味着模型本身必须用强化学习训练。</p><h3 id="_5-2-已有简单可靠的控制器" tabindex="-1">5.2 已有简单可靠的控制器 <a class="header-anchor" href="#_5-2-已有简单可靠的控制器" aria-label="Permalink to &quot;5.2 已有简单可靠的控制器&quot;">​</a></h3><p>固定目标速度跟踪、常规路径横向跟踪等问题，经常可以由比例控制、PID（比例—积分—微分）控制、Pure Pursuit（纯跟踪）或 Stanley 控制稳定解决。此时更重要的是分析模型误差、执行器约束、延迟和鲁棒性，而不是直接替换成策略网络。</p><h3 id="_5-3-无法承担真实探索风险" tabindex="-1">5.3 无法承担真实探索风险 <a class="header-anchor" href="#_5-3-无法承担真实探索风险" aria-label="Permalink to &quot;5.3 无法承担真实探索风险&quot;">​</a></h3><p>如果任务的失败代价很高，又没有可信仿真、离线数据、安全约束或备份策略，就缺少基本的训练条件。把“未来可部署”当作“现在可在线试错”，是危险的概念偷换。</p><h3 id="_5-4-没有可信评价指标" tabindex="-1">5.4 没有可信评价指标 <a class="header-anchor" href="#_5-4-没有可信评价指标" aria-label="Permalink to &quot;5.4 没有可信评价指标&quot;">​</a></h3><p>只有一个累计奖励，无法回答策略是否安全、是否泛化、是否稳定。连成功标准和失败边界都没有定义时，训练曲线上升只说明算法更擅长获得当前分数。</p><h3 id="_5-5-数据稀少且环境不可复现" tabindex="-1">5.5 数据稀少且环境不可复现 <a class="header-anchor" href="#_5-5-数据稀少且环境不可复现" aria-label="Permalink to &quot;5.5 数据稀少且环境不可复现&quot;">​</a></h3><p>强化学习通常需要大量交互。如果每次实验条件都不同、关键失败无法重放、数据覆盖不足，那么策略改进和环境波动会混在一起，结果很难解释。</p><h2 id="六、放到自动驾驶系统中重新判断" tabindex="-1">六、放到自动驾驶系统中重新判断 <a class="header-anchor" href="#六、放到自动驾驶系统中重新判断" aria-label="Permalink to &quot;六、放到自动驾驶系统中重新判断&quot;">​</a></h2><p><img src="'+h+'" alt="自动驾驶任务与方法边界"></p><h3 id="_6-1-感知层更像预测问题" tabindex="-1">6.1 感知层更像预测问题 <a class="header-anchor" href="#_6-1-感知层更像预测问题" aria-label="Permalink to &quot;6.1 感知层更像预测问题&quot;">​</a></h3><p>相机、激光雷达和毫米波雷达输入经过模型，输出目标、车道、占用栅格或自由空间。这些任务的核心通常是从数据中学习映射，标签与离线数据集更关键。强化学习可以参与主动感知或传感器调度，但不是所有感知任务的默认答案。</p><h3 id="_6-2-预测层需要概率而非试错" tabindex="-1">6.2 预测层需要概率而非试错 <a class="header-anchor" href="#_6-2-预测层需要概率而非试错" aria-label="Permalink to &quot;6.2 预测层需要概率而非试错&quot;">​</a></h3><p>交通参与者轨迹预测关心多模态未来、不确定性和交互影响。它可以作为强化学习环境的一部分，也可以由监督学习、生成模型或概率模型独立完成。预测模型输出未来分布，不等于它正在执行动作并接受奖励。</p><h3 id="_6-3-行为决策更接近强化学习主场" tabindex="-1">6.3 行为决策更接近强化学习主场 <a class="header-anchor" href="#_6-3-行为决策更接近强化学习主场" aria-label="Permalink to &quot;6.3 行为决策更接近强化学习主场&quot;">​</a></h3><p>变道、合流、无保护左转、交叉口通行和多车协作具有长期影响与策略互动。当前决策会改变其他参与者反应和后续机会，单步最优不一定带来整体最优。这些任务更符合序列决策结构，但仍需要强基线、仿真可信度和安全约束。</p><h3 id="_6-4-底层控制先问经典方法是否足够" tabindex="-1">6.4 底层控制先问经典方法是否足够 <a class="header-anchor" href="#_6-4-底层控制先问经典方法是否足够" aria-label="Permalink to &quot;6.4 底层控制先问经典方法是否足够&quot;">​</a></h3><p>本项目的 toy 环境给出了一个有用但边界明确的提醒：一维速度控制中，比例控制整体优于固定离散动作的表格型 Q-learning；车道保持中，Stanley 基线也明显强于粗离散 Q-learning。这个结果不能证明强化学习普遍不适合控制，只能说明在这些简化任务和当前实现下，复杂方法没有产生足以替换基线的价值。</p><h3 id="_6-5-安全层必须独立观察" tabindex="-1">6.5 安全层必须独立观察 <a class="header-anchor" href="#_6-5-安全层必须独立观察" aria-label="Permalink to &quot;6.5 安全层必须独立观察&quot;">​</a></h3><p>本项目的 safety shield（安全屏蔽）实验中，安全改善主要来自 Stanley 备份控制器与预测性动作筛选，而不是表格策略自行变安全。它说明“强化学习策略加安全层”与“策略本身具有安全性”是两件事。</p><p>一个工程系统需要分别报告任务表现、约束违反、备份接管和安全层介入。否则，高分策略可能只是频繁提出危险动作，再由外部控制器不断救场。</p><h2 id="七、建模前必须写清楚的问题" tabindex="-1">七、建模前必须写清楚的问题 <a class="header-anchor" href="#七、建模前必须写清楚的问题" aria-label="Permalink to &quot;七、建模前必须写清楚的问题&quot;">​</a></h2><h3 id="_7-1-智能体究竟控制什么" tabindex="-1">7.1 智能体究竟控制什么 <a class="header-anchor" href="#_7-1-智能体究竟控制什么" aria-label="Permalink to &quot;7.1 智能体究竟控制什么&quot;">​</a></h3><p>动作空间（Action Space，动作空间）可以是离散行为选择，也可以是连续的加速度、转角或轨迹参数。动作定义决定算法类别，也决定探索风险。不要在动作含义还模糊时讨论 DQN 或 PPO。</p><h3 id="_7-2-智能体能看到什么" tabindex="-1">7.2 智能体能看到什么 <a class="header-anchor" href="#_7-2-智能体能看到什么" aria-label="Permalink to &quot;7.2 智能体能看到什么&quot;">​</a></h3><p>状态（State，状态）描述环境的真实决策信息，观测（Observation，观测）描述智能体实际获得的信息。遮挡、噪声、延迟和传感器盲区会让两者不相同。把不可获得的真值塞进观测，会得到只能在仿真中成立的策略。</p><h3 id="_7-3-环境如何变化" tabindex="-1">7.3 环境如何变化 <a class="header-anchor" href="#_7-3-环境如何变化" aria-label="Permalink to &quot;7.3 环境如何变化&quot;">​</a></h3><p>转移模型（Transition Model，转移模型）描述状态如何受动作和随机因素影响。车辆动力学、执行器延迟、其他交通参与者反应以及仿真步长都会改变学习难度。如果关键动力学被省略，策略可能利用仿真漏洞。</p><h3 id="_7-4-成功与失败如何判定" tabindex="-1">7.4 成功与失败如何判定 <a class="header-anchor" href="#_7-4-成功与失败如何判定" aria-label="Permalink to &quot;7.4 成功与失败如何判定&quot;">​</a></h3><p>奖励之外，还要明确终止（Termination，任务终止）、截断（Truncation，时间或外部条件截断）和约束违反。任务成功、碰撞失败与达到最大步数不是同一类结束原因，评价时不能混在一起。</p><h3 id="_7-5-比较对象是什么" tabindex="-1">7.5 比较对象是什么 <a class="header-anchor" href="#_7-5-比较对象是什么" aria-label="Permalink to &quot;7.5 比较对象是什么&quot;">​</a></h3><p>至少要有一个简单、可靠、可解释的基线，并在相同初始条件、相同扰动和相同指标下比较。强化学习的平均回报不能与控制器的跟踪误差直接比，需要统一成任务成功率、误差、舒适性、效率与安全等可解释指标。</p><h3 id="_7-6-训练与评估如何隔离" tabindex="-1">7.6 训练与评估如何隔离 <a class="header-anchor" href="#_7-6-训练与评估如何隔离" aria-label="Permalink to &quot;7.6 训练与评估如何隔离&quot;">​</a></h3><p>评估场景要包含训练分布内、分布边界和未见扰动。训练随机种子与评估随机种子应区分，多次运行要报告波动。只展示表现最好的种子，会掩盖算法的不稳定性。</p><h2 id="八、一个最小判断框架" tabindex="-1">八、一个最小判断框架 <a class="header-anchor" href="#八、一个最小判断框架" aria-label="Permalink to &quot;八、一个最小判断框架&quot;">​</a></h2><p><img src="'+s+'" alt="是否使用强化学习的判断框架"></p><p>面对新任务，可以沿着图中的问题往下判断：</p><ul><li>输出是否会改变后续状态与数据。</li><li>是否需要为长期结果牺牲局部收益。</li><li>是否缺少逐步、唯一且可信的动作标签。</li><li>是否存在可重复交互环境或足够覆盖的离线数据。</li><li>是否已经建立简单而强的基线。</li><li>是否能把安全约束与任务奖励分别评价。</li></ul><p>如果多数答案是否定的，先使用更直接的方法。如果多数答案是肯定的，强化学习才值得进入候选方案，但这仍不代表某个具体算法已经被选中。</p><h2 id="九、常见误区" tabindex="-1">九、常见误区 <a class="header-anchor" href="#九、常见误区" aria-label="Permalink to &quot;九、常见误区&quot;">​</a></h2><h3 id="_9-1-强化学习不等于神经网络" tabindex="-1">9.1 强化学习不等于神经网络 <a class="header-anchor" href="#_9-1-强化学习不等于神经网络" aria-label="Permalink to &quot;9.1 强化学习不等于神经网络&quot;">​</a></h3><p>表格型 Q-learning 不需要神经网络，深度神经网络也可以用于监督学习。深度强化学习（Deep Reinforcement Learning，深度强化学习）只是用深度模型表示策略、价值函数或环境模型，并没有改变序列决策的本质。</p><h3 id="_9-2-回报更高不等于系统更安全" tabindex="-1">9.2 回报更高不等于系统更安全 <a class="header-anchor" href="#_9-2-回报更高不等于系统更安全" aria-label="Permalink to &quot;9.2 回报更高不等于系统更安全&quot;">​</a></h3><p>回报取决于奖励定义。安全约束若只是一个有限惩罚，就可能被其他收益抵消。安全关键任务需要独立的违反指标、最坏情况分析和失效保护。</p><h3 id="_9-3-仿真成功不等于可以上车" tabindex="-1">9.3 仿真成功不等于可以上车 <a class="header-anchor" href="#_9-3-仿真成功不等于可以上车" aria-label="Permalink to &quot;9.3 仿真成功不等于可以上车&quot;">​</a></h3><p>仿真中的传感器、动力学和交通参与者都可能比现实更干净。Sim-to-Real（仿真到现实）差距、长尾场景、软件延迟和硬件故障不会因为训练曲线平滑而消失。</p><h3 id="_9-4-算法复杂不等于研究进展" tabindex="-1">9.4 算法复杂不等于研究进展 <a class="header-anchor" href="#_9-4-算法复杂不等于研究进展" aria-label="Permalink to &quot;9.4 算法复杂不等于研究进展&quot;">​</a></h3><p>如果 PID 或 Stanley 已经稳定完成任务，换成更复杂的策略网络却没有带来可重复优势，这不是方法升级。真正的进展应该表现为更强的任务能力、更清楚的适用边界或更可信的安全证据。</p><h2 id="十、这一系列接下来怎么学" tabindex="-1">十、这一系列接下来怎么学 <a class="header-anchor" href="#十、这一系列接下来怎么学" aria-label="Permalink to &quot;十、这一系列接下来怎么学&quot;">​</a></h2><p>本系列会以《蘑菇书》的章节知识为主线，但不会逐页复述。每篇文章会把概念、公式、现代工具接口、最小实验和自动驾驶问题放在同一个学习闭环里。</p><p>后续内容将从智能体、环境、状态、动作和奖励的基本闭环开始，再进入马尔可夫决策过程（Markov Decision Process，马尔可夫决策过程）、价值函数、表格方法、策略梯度、DQN、PPO、演员—评论员、稀疏奖励、模仿学习、连续动作方法和安全强化学习。</p><p>下一篇将专门拆解“智能体、环境、状态、观测、动作、奖励”这些词。它们看起来简单，却决定了后面所有公式究竟在描述什么。</p><h2 id="十一、结语" tabindex="-1">十一、结语 <a class="header-anchor" href="#十一、结语" aria-label="Permalink to &quot;十一、结语&quot;">​</a></h2><p>强化学习最吸引人的地方，是让系统从交互中学习长期策略；它最容易被误用的地方，也是把任何“自动优化”都包装成强化学习。</p><p>判断一个问题是否适合强化学习，可以记住一句话：不是看它能不能套上算法，而是看它是否真的存在由行动改变未来的连续决策闭环。</p><p>先把问题建模清楚，再谈算法。这样做不会让学习变慢，反而会省掉大量没有意义的训练。</p><h2 id="十二、资料来源" tabindex="-1">十二、资料来源 <a class="header-anchor" href="#十二、资料来源" aria-label="Permalink to &quot;十二、资料来源&quot;">​</a></h2><p><a href="https://github.com/datawhalechina/easy-rl" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》项目主页与章节导航</a></p><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter1/chapter1.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第 1 章“强化学习基础”原始文档</a></p><p><a href="https://spinningup.openai.com/en/latest/spinningup/rl_intro.html" target="_blank" rel="noreferrer">OpenAI Spinning Up（OpenAI 强化学习入门资料）核心概念</a></p><p><a href="https://gymnasium.farama.org/main/introduction/migration_guide/" target="_blank" rel="noreferrer">Gymnasium（强化学习环境接口）迁移指南</a></p><p>本项目阶段研究总结 -- 项目内 <code>docs/2026_07_10_overall_research_summary.md</code></p><blockquote><p>版权说明：本文为基于公开资料与本项目实验记录重新组织的原创学习文章，不复刻《蘑菇书》原文插图。涉及原资料的概念框架已在上方标明来源。</p></blockquote>',113)])])}const f=e(p,[["render",d]]);export{P as __pageData,f as default};
